/**
 * Camera Recognition Component
 * Streaming vidéo + reconnaissance faciale + log en temps réel
 */

import React, { useRef, useState, useEffect } from "react";
import { attendanceAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  success: "#10B981",
  danger: "#EF4444",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0"
};

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const [isStreaming, setIsStreaming] = useState(false);
  const [status, setStatus] = useState("idle"); // idle, running, error
  const [recentDetections, setRecentDetections] = useState([]);
  const [stats, setStats] = useState({
    present_today: 0,
    absent_today: 0,
    active_students: 0
  });

  // Start camera
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 } }
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsStreaming(true);
        setStatus("running");
      }
    } catch (error) {
      console.error("Camera error:", error);
      setStatus("error");
      alert("❌ Accès à la caméra refusé ou indisponible");
    }
  };

  // Stop camera
  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      setIsStreaming(false);
      setStatus("idle");
    }
  };

  // Capture frame and recognize (simulate)
  const captureFrame = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    try {
      const context = canvasRef.current.getContext("2d");
      context.drawImage(videoRef.current, 0, 0, 640, 480);

      // Convert to base64 (in real app, would send actual embedding)
      const imageData = canvasRef.current.toDataURL("image/jpeg");

      // Simulate embedding (normally from ML pipeline)
      const fakeEmbedding = btoa(JSON.stringify({
        timestamp: Date.now(),
        confidence: Math.random() * 0.3 + 0.7
      }));

      // Call API
      const response = await attendanceAPI.recognize(fakeEmbedding);

      if (response.data.success) {
        addDetection({
          name: response.data.student,
          time: new Date().toLocaleTimeString("fr-FR"),
          confidence: (response.data.confidence * 100).toFixed(1)
        });
      }
    } catch (error) {
      console.error("Recognition error:", error);
    }
  };

  // Add detection to log
  const addDetection = (detection) => {
    setRecentDetections(prev => [
      { ...detection, id: Date.now() },
      ...prev
    ].slice(0, 10)); // Keep last 10
  };

  // Load stats
  useEffect(() => {
    const loadStats = async () => {
      try {
        const response = await attendanceAPI.getStats();
        setStats({
          present_today: response.data.present_today || 0,
          absent_today: response.data.absent_today || 0,
          active_students: response.data.active_students || 0
        });
      } catch (error) {
        console.error("Error loading stats:", error);
      }
    };

    loadStats();
  }, [recentDetections]);

  // Auto capture every 2 seconds when running
  useEffect(() => {
    if (isStreaming) {
      const interval = setInterval(() => {
        captureFrame();
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [isStreaming]);

  return (
    <div style={styles.container}>
      <div style={styles.grid}>
        {/* Camera Section */}
        <div style={styles.cameraSection}>
          <Card title="🎥 Flux vidéo en direct" subtitle="Reconnaissance faciale en temps réel">
            <div style={styles.cameraWrapper}>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                style={styles.video}
              />
              <canvas
                ref={canvasRef}
                width={640}
                height={480}
                style={{ display: "none" }}
              />

              {/* Status Indicator */}
              <div style={{
                ...styles.statusIndicator,
                backgroundColor: status === "running" ? COLORS.success : status === "error" ? COLORS.danger : "#E2E8F0",
                color: status === "running" ? "white" : status === "error" ? "white" : COLORS.textMuted
              }}>
                <span style={{
                  display: "inline-block",
                  width: "8px",
                  height: "8px",
                  borderRadius: "50%",
                  backgroundColor: status === "running" ? "white" : "currentColor",
                  marginRight: "6px",
                  animation: status === "running" ? "pulse 2s infinite" : "none"
                }} />
                {status === "running" ? "En direct" : status === "error" ? "Erreur" : "Arrêté"}
              </div>

              {/* Control Buttons */}
              <div style={styles.buttonGroup}>
                <button
                  onClick={startCamera}
                  disabled={isStreaming}
                  style={{
                    ...styles.btn,
                    ...styles.btnSuccess,
                    opacity: isStreaming ? 0.5 : 1
                  }}
                >
                  ▶️ Démarrer
                </button>
                <button
                  onClick={stopCamera}
                  disabled={!isStreaming}
                  style={{
                    ...styles.btn,
                    ...styles.btnDanger,
                    opacity: !isStreaming ? 0.5 : 1
                  }}
                >
                  ⏹️ Arrêter
                </button>
              </div>
            </div>
          </Card>
        </div>

        {/* Stats Section */}
        <div style={styles.statsSection}>
          <Card title="📊 Statistiques" subtitle="État actuel de la journée">
            <div style={styles.statsBox}>
              <StatItem
                label="Présents"
                value={stats.present_today}
                icon="✅"
                color={COLORS.success}
              />
              <StatItem
                label="Absents"
                value={stats.absent_today}
                icon="❌"
                color={COLORS.danger}
              />
              <StatItem
                label="Total inscrit"
                value={stats.active_students}
                icon="👥"
                color={COLORS.primary}
              />
            </div>
          </Card>

          {/* Recent Detections */}
          <Card title="🔍 Détections récentes" subtitle="Derniers visages reconnus">
            <div style={styles.detectionList}>
              {recentDetections.length === 0 ? (
                <p style={{ color: COLORS.textMuted, textAlign: "center" }}>
                  Aucune détection pour le moment
                </p>
              ) : (
                recentDetections.map(detection => (
                  <div key={detection.id} style={styles.detectionItem}>
                    <div>
                      <p style={styles.detectionName}>{detection.name}</p>
                      <p style={styles.detectionTime}>{detection.time}</p>
                    </div>
                    <ConfidenceBadge value={parseFloat(detection.confidence)} />
                  </div>
                ))
              )}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

/**
 * ============ SUB-COMPONENTS ============
 */

const Card = ({ children, title, subtitle }) => (
  <div style={styles.card}>
    <div style={styles.cardHeader}>
      <div>
        <h3 style={styles.cardTitle}>{title}</h3>
        {subtitle && <p style={styles.cardSubtitle}>{subtitle}</p>}
      </div>
    </div>
    <div style={styles.cardBody}>{children}</div>
  </div>
);

const StatItem = ({ label, value, icon, color }) => (
  <div style={styles.statItem}>
    <div style={{ ...styles.statIcon, color }}>
      {icon}
    </div>
    <div>
      <p style={styles.statLabel}>{label}</p>
      <p style={styles.statValue}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ value }) => {
  const percentage = (value * 100).toFixed(1);
  const getColor = () => {
    if (value >= 0.8) return { bg: "#DCFCE7", text: "#166534" };
    if (value >= 0.6) return { bg: "#FEF3C7", text: "#92400E" };
    return { bg: "#FEE2E2", text: "#991B1B" };
  };
  const colors = getColor();
  return (
    <span style={{
      ...styles.badge,
      backgroundColor: colors.bg,
      color: colors.text
    }}>
      {percentage}%
    </span>
  );
};

